    <header class="tc-aa__header">
        <div class="tc-aa__heading"><span class="tc-aa__heading-icon"><i class="bi <?php echo e($pagina['icono']); ?>"></i></span><div><?php if($tipo === 'globales'): ?><span class="tc-aa__eyebrow">Analítica y reportes</span><?php endif; ?><h1><?php echo e($pagina['titulo']); ?></h1><p><?php echo e($pagina['descripcion']); ?></p></div></div>
        <div class="tc-aa__actions"><?php $__currentLoopData = $pagina['acciones']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $accion): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if($accion[2] === 'exportar' && $puedeExportar): ?><details class="tc-aa__export-menu"><summary class="tc-aa__button <?php echo e($loop->last ? 'tc-aa__button--primary' : ''); ?>"><i class="bi <?php echo e($accion[1]); ?>"></i><?php echo e($accion[0]); ?> <i class="bi bi-chevron-down"></i></summary><div class="tc-aa__export-options"><a href="<?php echo e(route('management.reports.preview.export', ['tipo' => $tipo, 'format' => 'excel'] + request()->query())); ?>">Excel (.xlsx)</a><a href="<?php echo e(route('management.reports.preview.export', ['tipo' => $tipo, 'format' => 'pdf'] + request()->query())); ?>">PDF (.pdf)</a><a href="<?php echo e(route('management.reports.preview.export', ['tipo' => $tipo, 'format' => 'csv'] + request()->query())); ?>">CSV (.csv)</a></div></details><?php else: ?><button type="button" disabled title="La operación requiere una entidad y un permiso autorizados" class="tc-aa__button <?php echo e($loop->last ? 'tc-aa__button--primary' : ''); ?>"><i class="bi <?php echo e($accion[1]); ?>"></i><?php echo e($accion[0]); ?></button><?php endif; ?> <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div>
