    <form method="GET" class="tc-aa__card tc-aa__filters" aria-label="Filtros de consulta"><h2><i class="bi bi-funnel"></i> Filtros de consulta</h2><div class="tc-aa__filter-grid"><?php $__currentLoopData = $pagina['filtros']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as [$etiqueta, $nombreCampo, $marcador]): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><?php echo e($etiqueta); ?><?php if($marcador === 'fecha'): ?><input type="date" name="<?php echo e($nombreCampo); ?>" value="<?php echo e($filtros[$nombreCampo] ?? ''); ?>"><?php elseif($marcador === 'text'): ?><input type="search" name="<?php echo e($nombreCampo); ?>" value="<?php echo e($filtros[$nombreCampo] ?? ''); ?>" maxlength="120"><?php else: ?><select name="<?php echo e($nombreCampo); ?>" <?php if(in_array($nombreCampo, $pagina['filtrosBloqueados'], true)): echo 'disabled'; endif; ?>><option value=""><?php echo e($marcador); ?></option><?php $__currentLoopData = ($nombreCampo === 'reporte' ? $pagina['opcionesReportes'] : ($pagina['opcionesFiltros'][$nombreCampo] ?? [])); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $valor => $texto): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($valor); ?>" <?php if((string) ($filtros[$nombreCampo] ?? '') === (string) $valor): echo 'selected'; endif; ?>><?php echo e($texto); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><?php endif; ?></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><button type="submit" class="tc-aa__button tc-aa__button--primary"><i class="bi bi-search"></i> Aplicar filtros</button><a class="tc-aa__button" href="<?php echo e(route(request()->route()->getName())); ?>">Restablecer</a></div></form>
    <section class="tc-aa__card tc-aa__records"><div class="tc-aa__card-heading"><div><h2><?php echo e($pagina['tabla']); ?></h2><small>Total: <span data-aa-count><?php echo e($pagina['paginacion']?->total() ?? count($pagina['filas'])); ?></span> registros reales</small></div><span>Consulta de solo lectura</span></div><div class="tc-aa__table-wrap"><table><thead><tr><?php $__currentLoopData = $pagina['columnas']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $columna): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><th><?php echo e($columna); ?></th><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><th>Detalle</th></tr></thead><tbody><?php $__currentLoopData = $pagina['filas']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $fila): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr data-aa-row><?php $__currentLoopData = $fila; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $celda): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><td><?php if($loop->last && in_array(mb_strtolower((string) $celda), ['exito', 'exitoso', 'fallo', 'fallido', 'denegado', 'revertido', 'pendiente'], true)): ?><span class="tc-aa__badge <?php echo e(in_array(mb_strtolower((string) $celda), ['fallo', 'fallido', 'denegado'], true) ? 'tc-aa__badge--red' : (in_array(mb_strtolower((string) $celda), ['revertido', 'pendiente'], true) ? 'tc-aa__badge--amber' : '')); ?>"><?php echo e($celda); ?></span><?php else: ?><?php echo e($celda); ?><?php endif; ?></td><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><td><button type="button" data-aa-detail="<?php echo e($loop->index); ?>" aria-label="Ver detalle del registro"><i class="bi bi-eye"></i> Ver detalle</button></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div><p class="tc-aa__empty" data-aa-empty <?php if(count($pagina['filas']) > 0): ?> hidden <?php endif; ?>>No hay registros para los filtros aplicados.</p>
        <?php if($pagina['paginacion']): ?><footer class="tc-aa__card-heading"><span>Página <?php echo e($pagina['paginacion']->currentPage()); ?> de <?php echo e($pagina['paginacion']->lastPage()); ?></span><nav aria-label="Paginación"><?php if($pagina['paginacion']->previousPageUrl()): ?><a href="<?php echo e($pagina['paginacion']->previousPageUrl()); ?>">Anterior</a><?php endif; ?> <?php if($pagina['paginacion']->nextPageUrl()): ?><a href="<?php echo e($pagina['paginacion']->nextPageUrl()); ?>">Siguiente</a><?php endif; ?></nav></footer><?php endif; ?>
    </section>
    <div class="tc-aa__bottom"><section class="tc-aa__card"><h2><?php echo e($pagina['grafico']); ?></h2><div class="tc-aa__chart"><?php $__empty_1 = true; $__currentLoopData = $pagina['barras']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $barra): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="tc-aa__bar"><strong><?php echo e($barra[2]); ?></strong><span style="--altura: <?php echo e($barra[1]); ?>%"></span><small><?php echo e($barra[0]); ?></small></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><p class="tc-aa__empty">Sin datos para graficar.</p><?php endif; ?></div></section><section class="tc-aa__card"><h2><?php echo e($pagina['resumen']); ?></h2><ul class="tc-aa__summary"><?php $__empty_1 = true; $__currentLoopData = $pagina['resumen_filas']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $fila): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><li><span><i></i><?php echo e($fila[0]); ?></span><strong><?php echo e($fila[1]); ?></strong></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><li><span>Sin registros</span><strong>0</strong></li><?php endif; ?></ul></section></div>
    <dialog class="tc-aa__dialog" data-aa-dialog aria-labelledby="tc-aa-dialog-title"><div class="tc-aa__dialog-card"><header><span class="tc-aa__heading-icon"><i class="bi <?php echo e($pagina['icono']); ?>"></i></span><div><span><?php echo e($pagina['titulo']); ?></span><h2 id="tc-aa-dialog-title">Detalle del registro</h2><p>Información real de solo lectura.</p></div><button type="button" data-aa-close aria-label="Cerrar"><i class="bi bi-x-lg"></i></button></header><div class="tc-aa__dialog-body"><div class="tc-aa__dialog-fields" data-aa-detail-data></div><p class="tc-aa__dialog-note">Los registros de auditoría no se modifican desde esta consulta.</p></div><footer><button type="button" class="tc-aa__button" data-aa-close>Cancelar</button><button type="button" data-aa-previous hidden>Anterior</button><button type="button" data-aa-next hidden>Siguiente</button><button type="button" class="tc-aa__button tc-aa__button--primary" hidden>Confirmar</button></footer></div></dialog></section>
